package com.appointmentprep.common;

import java.security.SecureRandom;
import java.time.Clock;
import java.util.UUID;
import org.springframework.stereotype.Component;

/**
 * UUIDv7 IDs (RFC 9562), generated by the application (TECHNICAL_DESIGN §5.3). They sort by
 * creation time and don't reveal record counts.
 *
 * <p>Layout: 48-bit Unix milliseconds from the injected {@link Clock}, version 7, a 12-bit counter
 * (RFC 9562 §6.2 method 1) so IDs within the same millisecond still sort in creation order, the
 * variant, then 62 random bits.
 */
@Component
public class IdGenerator {

  private static final int COUNTER_MAX = 0xFFF;

  private final Clock clock;
  private final SecureRandom random = new SecureRandom();
  private long lastMillis = -1;
  private int counter;

  public IdGenerator(Clock clock) {
    this.clock = clock;
  }

  public synchronized UUID next() {
    long millis = clock.millis();
    if (millis > lastMillis) {
      lastMillis = millis;
      // Start in the lower half so there is room to count up within this millisecond.
      counter = random.nextInt((COUNTER_MAX + 1) / 2);
    } else if (counter < COUNTER_MAX) {
      // Same millisecond, or the clock went backwards: keep counting so IDs stay monotonic.
      counter++;
    } else {
      // Counter exhausted: borrow the next millisecond.
      lastMillis++;
      counter = 0;
    }
    long msb = (lastMillis << 16) | (0x7L << 12) | counter;
    long lsb = (random.nextLong() & 0x3FFF_FFFF_FFFF_FFFFL) | 0x8000_0000_0000_0000L;
    return new UUID(msb, lsb);
  }
}
